"""Tests for HairEditorService: finding the asset blends, telling the old asset pack apart, image pixel access
and wiring a texture into the hair shader."""

import os
import json

import bpy
import pytest

from .. import dynamic_import, LocationService

HairEditorService = dynamic_import("mpfb.services.haireditorservices", "HairEditorService")

# hair.blend sizes of the two published versions of the hair editor asset pack
_OLD_PACK_HAIR_BLEND_BYTES = 19608264
_CURRENT_PACK_HAIR_BLEND_BYTES = 27310677


@pytest.fixture
def fake_data_dirs(tmp_path, monkeypatch):
    """Point the user and the system data directories at empty temp dirs, with a clean blend path cache."""
    user_dir = tmp_path / "user"
    system_dir = tmp_path / "system"
    user_dir.mkdir()
    system_dir.mkdir()

    def user_data(sub_path=None):
        return str(user_dir / sub_path) if sub_path else str(user_dir)

    def mpfb_data(sub_path=None):
        return str(system_dir / sub_path) if sub_path else str(system_dir)

    monkeypatch.setattr(LocationService, "get_user_data", user_data)
    monkeypatch.setattr(LocationService, "get_mpfb_data", mpfb_data)
    # The cache would otherwise hand back the real pack, and the paths found here must not outlive the test
    monkeypatch.setattr(HairEditorService, "_BLEND_PATH_CACHE", {})
    return user_dir, system_dir


def _write_blend(data_dir, name="hair", size=16):
    """A fake asset blend of the given size. Only its location and size matter to the service."""
    folder = data_dir / "hair" / "haireditor"
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / f"{name}.blend"
    with open(path, "wb") as blend:
        blend.truncate(size)
    return os.path.realpath(str(path))


def test_haireditorservice_exists():
    """HairEditorService"""
    assert HairEditorService is not None, "HairEditorService can be imported"


def test_haireditorservice_cannot_be_instanced():
    """Only static methods, like every other service."""
    with pytest.raises(RuntimeError):
        HairEditorService()


def test_no_blend_means_nothing_is_installed(fake_data_dirs):
    assert HairEditorService.get_hair_blend_path() is None
    assert HairEditorService.get_fur_blend_path() is None
    assert not HairEditorService.is_hair_asset_installed()
    assert not HairEditorService.is_fur_asset_installed()


def test_blend_is_found_in_the_system_data_dir(fake_data_dirs):
    """The asset pack normally unpacks into the addon data folder."""
    _user_dir, system_dir = fake_data_dirs
    expected = _write_blend(system_dir, "hair")
    assert HairEditorService.get_hair_blend_path() == expected
    assert HairEditorService.is_hair_asset_installed()
    # Hair and fur are separate blends, one being there says nothing about the other
    assert not HairEditorService.is_fur_asset_installed()


def test_user_data_dir_wins_over_the_system_one(fake_data_dirs):
    """A pack installed in the user data dir is preferred, so it can override the one shipped with the addon."""
    user_dir, system_dir = fake_data_dirs
    _write_blend(system_dir, "fur")
    expected = _write_blend(user_dir, "fur")
    assert HairEditorService.get_fur_blend_path() == expected


def test_a_directory_named_like_the_blend_is_not_a_blend(fake_data_dirs):
    _user_dir, system_dir = fake_data_dirs
    (system_dir / "hair" / "haireditor" / "hair.blend").mkdir(parents=True)
    assert HairEditorService.get_hair_blend_path() is None


def test_found_blend_path_is_cached(fake_data_dirs):
    """The panel asks on every redraw, so a found path is not looked up again."""
    _user_dir, system_dir = fake_data_dirs
    expected = _write_blend(system_dir, "hair")
    assert HairEditorService.get_hair_blend_path() == expected
    os.remove(expected)
    assert HairEditorService.get_hair_blend_path() == expected, "a found path should be served from the cache"


def test_missing_blend_is_noticed_once_installed(fake_data_dirs):
    """A missing blend is only cached for a moment, so a pack installed while blender runs shows up on its own."""
    _user_dir, system_dir = fake_data_dirs
    assert HairEditorService.get_hair_blend_path() is None
    expected = _write_blend(system_dir, "hair")

    # Still within the time the miss is remembered
    assert HairEditorService.get_hair_blend_path() is None

    # Age the remembered miss past its expiry instead of sleeping
    path, _looked_up_at = HairEditorService._BLEND_PATH_CACHE["hair"]
    HairEditorService._BLEND_PATH_CACHE["hair"] = (path, 0.0)
    assert HairEditorService.get_hair_blend_path() == expected


def test_outdated_threshold_lies_between_the_two_published_packs():
    """The old pack is told apart by the size of hair.blend alone, so the threshold has to split the two."""
    threshold = HairEditorService._OUTDATED_HAIR_BLEND_MAX_BYTES
    assert _OLD_PACK_HAIR_BLEND_BYTES < threshold < _CURRENT_PACK_HAIR_BLEND_BYTES


def test_old_pack_is_reported_as_outdated(fake_data_dirs):
    _user_dir, system_dir = fake_data_dirs
    _write_blend(system_dir, "hair", size=_OLD_PACK_HAIR_BLEND_BYTES)
    assert HairEditorService.is_hair_pack_outdated()


def test_current_pack_is_not_reported_as_outdated(fake_data_dirs):
    _user_dir, system_dir = fake_data_dirs
    _write_blend(system_dir, "hair", size=_CURRENT_PACK_HAIR_BLEND_BYTES)
    assert not HairEditorService.is_hair_pack_outdated()


def test_no_pack_is_not_reported_as_outdated(fake_data_dirs):
    """Without any pack the panel says it is not installed, an extra "outdated" warning would only confuse."""
    assert not HairEditorService.is_hair_pack_outdated()


def test_outdated_check_survives_the_blend_disappearing(fake_data_dirs):
    """The path is cached, so the file can be gone by the time its size is read. That must not raise from a draw()."""
    _user_dir, system_dir = fake_data_dirs
    path = _write_blend(system_dir, "hair", size=1024)
    assert HairEditorService.get_hair_blend_path() == path
    os.remove(path)
    assert not HairEditorService.is_hair_pack_outdated()


def test_fur_blend_size_does_not_matter(fake_data_dirs):
    """Only the hair blend changed between the packs, a small fur blend next to a current hair blend is fine."""
    _user_dir, system_dir = fake_data_dirs
    _write_blend(system_dir, "hair", size=_CURRENT_PACK_HAIR_BLEND_BYTES)
    _write_blend(system_dir, "fur", size=1024)
    assert not HairEditorService.is_hair_pack_outdated()


def test_image_pixels_round_trip():
    """read_image_pixels and write_image_pixels are the only way the bake touches pixels, so they must agree."""
    import numpy as np

    # Float buffer, a byte image would round every value to 1/255
    image = bpy.data.images.new("haireditorservice_pixels", 4, 2, alpha=True, float_buffer=True)
    try:
        values = np.linspace(0.0, 1.0, 4 * 2 * 4, dtype=np.float32)
        HairEditorService.write_image_pixels(image, values.reshape(2, 4, 4))
        read_back = HairEditorService.read_image_pixels(image)
        assert read_back.dtype == np.float32
        assert read_back.shape == (4 * 2 * 4,)
        assert np.allclose(read_back, values, atol=1e-6)
    finally:
        bpy.data.images.remove(image)


def _shader_with_two_colour_links():
    """A material with a group node holding two Principled shaders, both coloured by an RGB node.

    That is how the asset hair shader ("Hair shader EEVEE") is put together.
    """
    group = bpy.data.node_groups.new("Hair shader EEVEE test", 'ShaderNodeTree')
    nodes = group.nodes
    links = group.links
    colour = nodes.new('ShaderNodeRGB')
    colour.name = "Colour source"
    shaders = []
    for name in ("Principled A", "Principled B"):
        shader = nodes.new('ShaderNodeBsdfPrincipled')
        shader.name = name
        links.new(colour.outputs['Color'], shader.inputs[0])
        shaders.append(shader)

    material = bpy.data.materials.new("haireditorservice_shader")
    material.use_nodes = True
    group_node = material.node_tree.nodes.new('ShaderNodeGroup')
    group_node.node_tree = group
    return material, group, group_node, colour, shaders


def _colour_sources(shaders):
    return [[link.from_node.name for link in shader.inputs[0].links] for shader in shaders]


def test_texture_replaces_the_colour_links_and_they_come_back():
    material, group, group_node, colour, shaders = _shader_with_two_colour_links()
    try:
        image_node = group.nodes.new('ShaderNodeTexImage')
        image_node.name = "Texture"
        key = "_saved_base_color_links"

        HairEditorService.join_texture_node_to_shader(image_node, shaders, group_node, group.links, key, True)
        assert _colour_sources(shaders) == [["Texture"], ["Texture"]]
        assert json.loads(group_node[key]) == {"Principled A": [["Colour source", "Color"]],
                                               "Principled B": [["Colour source", "Color"]]}

        HairEditorService.restore_shader_links(image_node, shaders, group_node, group.nodes, group.links, key)
        assert _colour_sources(shaders) == [["Colour source"], ["Colour source"]]
        assert key not in group_node, "the saved links are only needed until they are restored"
    finally:
        bpy.data.materials.remove(material)
        bpy.data.node_groups.remove(group)


def test_texture_join_without_storing_keeps_earlier_saved_links():
    """Swapping one texture for another must not save the first texture's links as the colours to go back to."""
    material, group, group_node, colour, shaders = _shader_with_two_colour_links()
    try:
        key = "_saved_base_color_links"
        first = group.nodes.new('ShaderNodeTexImage')
        HairEditorService.join_texture_node_to_shader(first, shaders, group_node, group.links, key, True)
        saved = group_node[key]

        second = group.nodes.new('ShaderNodeTexImage')
        second.name = "Second texture"
        HairEditorService.join_texture_node_to_shader(second, shaders, group_node, group.links, key, False)
        assert group_node[key] == saved
        assert _colour_sources(shaders) == [["Second texture"], ["Second texture"]]
    finally:
        bpy.data.materials.remove(material)
        bpy.data.node_groups.remove(group)


def test_restore_without_saved_links_only_disconnects_the_texture():
    material, group, group_node, colour, shaders = _shader_with_two_colour_links()
    try:
        for shader in shaders:
            for link in list(shader.inputs[0].links):
                group.links.remove(link)
        image_node = group.nodes.new('ShaderNodeTexImage')
        for shader in shaders:
            group.links.new(image_node.outputs['Color'], shader.inputs[0])

        HairEditorService.restore_shader_links(image_node, shaders, group_node, group.nodes, group.links, "missing")
        assert _colour_sources(shaders) == [[], []]
    finally:
        bpy.data.materials.remove(material)
        bpy.data.node_groups.remove(group)


def test_restore_skips_a_colour_source_which_was_deleted():
    material, group, group_node, colour, shaders = _shader_with_two_colour_links()
    try:
        key = "_saved_base_color_links"
        image_node = group.nodes.new('ShaderNodeTexImage')
        HairEditorService.join_texture_node_to_shader(image_node, shaders, group_node, group.links, key, True)
        group.nodes.remove(colour)

        HairEditorService.restore_shader_links(image_node, shaders, group_node, group.nodes, group.links, key)
        assert _colour_sources(shaders) == [[], []]
        assert key not in group_node
    finally:
        bpy.data.materials.remove(material)
        bpy.data.node_groups.remove(group)


def test_restore_survives_garbage_in_the_saved_links():
    """The saved links are a json string in a custom property, which a user (or an old file) can break."""
    material, group, group_node, colour, shaders = _shader_with_two_colour_links()
    try:
        key = "_saved_base_color_links"
        group_node[key] = "{not json"
        HairEditorService.restore_shader_links(None, shaders, group_node, group.nodes, group.links, key)
        assert _colour_sources(shaders) == [["Colour source"], ["Colour source"]]
        assert key not in group_node
    finally:
        bpy.data.materials.remove(material)
        bpy.data.node_groups.remove(group)


@pytest.fixture
def render_scene():
    """An object in a collection of its own, inside a parent collection, and everything removed afterwards."""
    scene = bpy.context.scene
    parent = bpy.data.collections.new("haireditorservice_parent")
    child = bpy.data.collections.new("haireditorservice_child")
    scene.collection.children.link(parent)
    parent.children.link(child)
    obj = bpy.data.objects.new("haireditorservice_rendered", bpy.data.lights.new("haireditorservice_light", 'POINT'))
    child.objects.link(obj)
    yield scene, parent, child, obj
    light = obj.data
    bpy.data.objects.remove(obj)
    bpy.data.lights.remove(light)
    bpy.data.collections.remove(child)
    bpy.data.collections.remove(parent)


def _rendered(scene, obj):
    return HairEditorService.is_rendered(obj, scene, bpy.context.view_layer)


def test_object_renders_by_default(render_scene):
    scene, _parent, _child, obj = render_scene
    assert _rendered(scene, obj)


def test_object_hidden_only_in_the_viewport_still_renders(render_scene):
    """The bake used to go by viewport visibility, so such an object was neither hidden nor counted as a light."""
    scene, _parent, _child, obj = render_scene
    obj.hide_set(True)
    obj.hide_viewport = True
    assert not obj.visible_get()
    assert _rendered(scene, obj)


def test_object_hidden_for_render_does_not_render(render_scene):
    scene, _parent, _child, obj = render_scene
    obj.hide_render = True
    assert obj.visible_get(), "it still shows in the viewport"
    assert not _rendered(scene, obj)


def test_collection_hidden_for_render_hides_what_is_inside(render_scene):
    scene, parent, _child, obj = render_scene
    parent.hide_render = True
    assert not _rendered(scene, obj), "hidden through a parent collection"


def test_object_in_a_second_rendered_collection_still_renders(render_scene):
    scene, parent, _child, obj = render_scene
    parent.hide_render = True
    scene.collection.objects.link(obj)
    try:
        assert _rendered(scene, obj)
    finally:
        scene.collection.objects.unlink(obj)


def test_excluded_collection_does_not_render(render_scene):
    scene, parent, _child, obj = render_scene
    layer_collection = next(item for item in bpy.context.view_layer.layer_collection.children if item.collection == parent)
    layer_collection.exclude = True
    try:
        assert not _rendered(scene, obj)
    finally:
        layer_collection.exclude = False


def test_object_outside_the_scene_does_not_render():
    obj = bpy.data.objects.new("haireditorservice_nowhere", None)
    try:
        assert not HairEditorService.is_rendered(obj, bpy.context.scene, bpy.context.view_layer)
    finally:
        bpy.data.objects.remove(obj)
